import gurobipy as gp
from gurobipy import GRB
product_records = [r['values'] for r in LEGACY_RECORDS if r['source'] == 'product_resources.csv']
resource_records = [r['values'] for r in LEGACY_RECORDS if r['source'] == 'resource_limits.csv']
products = []
a = {}
b = {}
c = {}
p = {}
for rec in product_records:
    prod = rec['Product']
    products.append(prod)
    try:
        a[prod] = float(rec['LaborHours'])
        b[prod] = float(rec['MaterialA'])
        c[prod] = float(rec['MaterialB'])
        p[prod] = float(rec['Profit'])
    except Exception as e:
        raise ValueError(f'Missing or invalid data for {prod}: {e}')
if len(products) != 141:
    raise ValueError(f'Expected 141 products, found {len(products)}')
resource_limits = {}
for rec in resource_records:
    resource_limits[rec['Resource']] = float(rec['MonthlyLimit'])
if set(resource_limits.keys()) != {'LaborHours', 'MaterialA', 'MaterialB'}:
    raise ValueError(f'Resource limits missing or extra: {resource_limits.keys()}')
widget3 = 'Widget3'
if widget3 not in products:
    raise ValueError('Widget3 not found in products')
m = gp.Model('widget_portfolio')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
y = m.addVar(lb=0, ub=1500, vtype=GRB.CONTINUOUS, name='y')
z = m.addVar(lb=0, vtype=GRB.CONTINUOUS, name='z')
m.setObjective(gp.quicksum((p[i] * x[i] for i in products)) + 300 * y - 200 * z, GRB.MAXIMIZE)
m.addConstr(gp.quicksum((a[i] * x[i] for i in products)) <= resource_limits['LaborHours'], name='labor')
m.addConstr(gp.quicksum((b[i] * x[i] for i in products)) <= resource_limits['MaterialA'], name='matA')
m.addConstr(gp.quicksum((c[i] * x[i] for i in products)) <= resource_limits['MaterialB'], name='matB')
m.addConstr(5 * x[widget3] == y + z, name='catalyst_balance')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')